// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address caller, bytes32 guess) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        vm.deal(caller, 2 ether);

        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + 2);

        vm.prank(caller);
        c.settle();

        bool ok;
        vm.prank(caller);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
